"""Tensor-parallel linear layers (Megatron-style).

Weight layout follows torch.nn.Linear: weight has shape (out_features, in_features).

- ColumnParallelLinear: the output dimension is partitioned across ranks
  (each rank holds out_features / world_size rows of the nn.Linear weight,
  i.e. a column block of W^T). Outputs are all-gathered along the last dim.
- RowParallelLinear: the input dimension is partitioned across ranks
  (each rank holds in_features / world_size columns of the nn.Linear weight,
  i.e. a row block of W^T). Partial outputs are all-reduced (summed).
"""

import torch
import torch.distributed as dist
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _divide(n, d):
    assert n % d == 0, f"{n} is not divisible by {d}"
    return n // d


# ---------------------------------------------------------------------------
# Communication primitives with autograd support
# ---------------------------------------------------------------------------

def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous().clone()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _all_gather_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


def _split_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    size = _divide(x.size(-1), ws)
    r = _rank()
    return x[..., r * size:(r + 1) * size].contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad)


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x)

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: split last dim, keep local chunk. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _all_gather_last_dim(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: split."""

    @staticmethod
    def forward(ctx, x):
        return _all_gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last_dim(grad)


# ---------------------------------------------------------------------------
# Layers
# ---------------------------------------------------------------------------

class ColumnParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.output_size_per_partition = _divide(out_features, self.world_size)

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != "
            f"{(out_features, in_features)}"
        )
        n = self.output_size_per_partition
        shard = master_weight.detach()[self.rank * n:(self.rank + 1) * n, :]
        self.weight = torch.nn.Parameter(shard.clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(n, dtype=self.weight.dtype, device=self.weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(out)


class RowParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.input_size_per_partition = _divide(in_features, self.world_size)

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != "
            f"{(out_features, in_features)}"
        )
        n = self.input_size_per_partition
        shard = master_weight.detach()[:, self.rank * n:(self.rank + 1) * n]
        self.weight = torch.nn.Parameter(shard.clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(out_features, dtype=self.weight.dtype,
                            device=self.weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split it here) or an already
        # partitioned input (e.g. output of a ColumnParallelLinear shard).
        if self.world_size > 1 and x.size(-1) == self.in_features:
            x = _ScatterToParallelRegion.apply(x)
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
